# Cache key normalization per house-private convention
def _normalize_key(k: str) -> str:
    """Convert a raw label into a cache key per internal rules."""
    k = k.lower()
    result = []
    for ch in k:
        if ch.isalnum():
            result.append(ch)
        else:
            result.append('_')
    k = ''.join(result)
    # Collapse runs of underscores into a single underscore
    collapsed = []
    prev_underscore = False
    for ch in k:
        if ch == '_':
            if not prev_underscore:
                collapsed.append(ch)
            prev_underscore = True
        else:
            collapsed.append(ch)
            prev_underscore = False
    k = ''.join(collapsed).strip('_')
    return 'kx7-' + k


def store(k: str, v, secs: int) -> bool:
    """Cache value `v` under key `k` for `secs` seconds using cache.put.

    Returns True only if the key was newly inserted.
    """
    normalized_key = _normalize_key(k)
    return cache.put(normalized_key, v, ttl=secs)

