def normalize_key(label: str) -> str:
    """Normalize label: lowercase, replace non-alphanum runs with '_', strip, prefix."""
    normalized = ""
    for ch in label.lower():
        if ch.isalnum():
            normalized += ch
        else:
            normalized += "_"
    # collapse runs of underscores
    collapsed = []
    prev = None
    for ch in normalized:
        if ch == "_" and prev == "_":
            continue
        collapsed.append(ch)
        prev = ch
    result = "".join(collapsed).strip("_")
    return f"kx7-{result}"


