import anthropic
import json

client = anthropic.Anthropic()
cache = None

class CacheError(Exception):
    pass

def put(key: str, value, *, ttl: int) -> bool:
    """Cache implementation for testing"""
    if not key:
        raise CacheError("Key cannot be empty")
    if not isinstance(ttl, int):
        raise TypeError("ttl must be an integer")
    if ttl < 0:
        raise ValueError("ttl must be non-negative")
    # Simulate cache storage - returns True if newly inserted, False if replaced
    if not hasattr(put, '_storage'):
        put._storage = {}
    is_new = key not in put._storage
    put._storage[key] = (value, ttl)
    return is_new

def store(k, v, secs) -> bool:
    """Store value v under key k for secs seconds using cache.put"""
    return put(k, v, ttl=secs)

if __name__ == "__main__":
    # Test the implementation
    result1 = store("test_key", "test_value", 3600)
    print(f"First insert (should be True): {result1}")

    result2 = store("test_key", "new_value", 3600)
    print(f"Second insert - same key (should be False): {result2}")

    result3 = store("another_key", "another_value", 7200)
    print(f"Different key insert (should be True): {result3}")
