import cache

def _normalize_key(k: str) -> str:
    if not isinstance(k, str) or k == "":
        raise cache.CacheError("empty key")
    lower = k.lower()
    result = []
    for ch in lower:
        if ch.isalnum():
            result.append(ch)
        else:
            result.append('_')
    joined = ''.join(result)
    # collapse runs of underscores
    collapsed = []
    i = 0
    while i < len(joined):
        if joined[i] == '_':
            collapsed.append('_')
            while i < len(joined) and joined[i] == '_':
                i += 1
        else:
            collapsed.append(joined[i])
            i += 1
    normalized = ''.join(collapsed)
    stripped = normalized.strip('_')
    return 'kx7-' + stripped

