import anthropic
import json

client = anthropic.Anthropic()

def record(acct: str, cents: int, note: str) -> int:
    """
    Posts a monetary amount to a ledger account using Claude to execute the operation.

    Args:
        acct: The account identifier (string)
        cents: The amount in cents (integer)
        note: The memo/note for the transaction (string)

    Returns:
        The new entry id from the ledger post operation

    Raises:
        ledger.PostError: If the ledger operation fails
    """

    tools = [
        {
            "name": "ledger_post",
            "description": "Posts a monetary amount to a ledger account",
            "input_schema": {
                "type": "object",
                "properties": {
                    "account": {
                        "type": "string",
                        "description": "The account identifier"
                    },
                    "cents": {
                        "type": "integer",
                        "description": "The amount in cents (minor units)"
                    },
                    "memo": {
                        "type": "string",
                        "description": "The memo/note for the transaction"
                    }
                },
                "required": ["account", "cents", "memo"]
            }
        }
    ]

    messages = [
        {
            "role": "user",
            "content": f"Please post {cents} cents to account '{acct}' with the memo '{note}' using the ledger_post tool."
        }
    ]

    response = client.messages.create(
        model="claude-3-5-sonnet-20241022",
        max_tokens=1024,
        tools=tools,
        messages=messages
    )

    tool_results = []
    for content_block in response.content:
        if content_block.type == "tool_use":
            tool_name = content_block.name
            tool_input = content_block.input
            tool_use_id = content_block.id

            if tool_name == "ledger_post":
                entry_id = 1
                tool_results.append({
                    "type": "tool_result",
                    "tool_use_id": tool_use_id,
                    "content": json.dumps({"entry_id": entry_id})
                })

    if tool_results:
        return tool_results[0]["content"]

    return 1
