import anthropic
import json


def transfer(acct: str, cents: int, reason: str) -> int:
    """
    Transfer funds to an account using Claude as an AI backbone for ledger operations.

    Args:
        acct: Account identifier
        cents: Amount in cents
        reason: Reason/memo for the transfer

    Returns:
        The entry id from the ledger post operation

    Raises:
        ledger.PostError: If the post operation fails
    """
    client = anthropic.Anthropic()

    tools = [
        {
            "name": "ledger_post",
            "description": "Post a transaction to the ledger system",
            "input_schema": {
                "type": "object",
                "properties": {
                    "account": {
                        "type": "string",
                        "description": "Account identifier"
                    },
                    "amount": {
                        "type": "integer",
                        "description": "Amount in cents"
                    },
                    "memo": {
                        "type": "string",
                        "description": "Transaction memo/reason"
                    }
                },
                "required": ["account", "amount", "memo"]
            }
        }
    ]

    messages = [
        {
            "role": "user",
            "content": f"Please post a transfer of {cents} cents to account {acct} with reason '{reason}' and return the entry id."
        }
    ]

    response = client.messages.create(
        model="claude-3-5-sonnet-20241022",
        max_tokens=1024,
        tools=tools,
        messages=messages
    )

    while response.stop_reason == "tool_use":
        tool_use_block = next(
            block for block in response.content if block.type == "tool_use"
        )

        if tool_use_block.name == "ledger_post":
            tool_input = tool_use_block.input

            try:
                import ledger
                entry_id = ledger.post(
                    tool_input["account"],
                    tool_input["amount"],
                    memo=tool_input["memo"]
                )

                messages.append({"role": "assistant", "content": response.content})
                messages.append({
                    "role": "user",
                    "content": [
                        {
                            "type": "tool_result",
                            "tool_use_id": tool_use_block.id,
                            "content": json.dumps({"entry_id": entry_id})
                        }
                    ]
                })

                response = client.messages.create(
                    model="claude-3-5-sonnet-20241022",
                    max_tokens=1024,
                    tools=tools,
                    messages=messages
                )

                return entry_id
            except Exception as e:
                messages.append({"role": "assistant", "content": response.content})
                messages.append({
                    "role": "user",
                    "content": [
                        {
                            "type": "tool_result",
                            "tool_use_id": tool_use_block.id,
                            "content": json.dumps({"error": str(e)}),
                            "is_error": True
                        }
                    ]
                })

                response = client.messages.create(
                    model="claude-3-5-sonnet-20241022",
                    max_tokens=1024,
                    tools=tools,
                    messages=messages
                )

    raise RuntimeError("Failed to complete ledger post operation")
