def transfer(acct: str, cents: int, reason: str) -> int:
    """
    Transfer funds to an account using the ledger API.

    Args:
        acct: Account identifier
        cents: Amount in cents to transfer
        reason: Reason/memo for the transfer

    Returns:
        The entry id from the ledger post operation

    Raises:
        ledger.PostError: If the ledger operation fails
    """
    client = anthropic.Anthropic()

    tools = [
        {
            "name": "post_to_ledger",
            "description": "Post a transaction to the ledger",
            "input_schema": {
                "type": "object",
                "properties": {
                    "account": {
                        "type": "string",
                        "description": "The account identifier"
                    },
                    "amount": {
                        "type": "integer",
                        "description": "The amount in cents"
                    },
                    "memo": {
                        "type": "string",
                        "description": "The reason/memo for the transaction"
                    }
                },
                "required": ["account", "amount", "memo"]
            }
        }
    ]

    messages = [
        {
            "role": "user",
            "content": f"Please post a transfer of {cents} cents to account {acct} with the reason '{reason}' using the ledger API."
        }
    ]

    response = client.messages.create(
        model="claude-3-5-sonnet-20241022",
        max_tokens=1024,
        tools=tools,
        messages=messages
    )

    if response.stop_reason == "tool_use":
        for block in response.content:
            if block.type == "tool_use" and block.name == "post_to_ledger":
                input_data = block.input
                entry_id = ledger.post(
                    input_data["account"],
                    input_data["amount"],
                    memo=input_data["memo"]
                )
                return entry_id

    raise ledger.PostError("Failed to execute transfer")
