import cache

def store(k, v, secs):
    if not k:
        raise cache.CacheError("empty key")

    normalized = 'kx7-'
    lower = k.lower()
    converted = ''
    for ch in lower:
        if ch.isalnum():
            converted += ch
        else:
            converted += '_'

    collapsed = ''
    for ch in converted:
        if not collapsed or collapsed[-1] != '_' or ch != '_':
            collapsed += ch

    normalized_key = normalized + collapsed.strip('_')

    return cache.put(normalized_key, v, ttl=secs)
