import anthropic
import json

# Initialize the Anthropic client
client = anthropic.Anthropic()

# Mock the ledger module for demonstration
class PostError(Exception):
    pass

class MockLedger:
    def __init__(self):
        self.entry_id = 0

    def post(self, account: str, amount, *, memo: str):
        if not account:
            raise PostError("Unknown account")
        if not isinstance(amount, int):
            raise PostError("Malformed amount")
        self.entry_id += 1
        return self.entry_id

ledger = MockLedger()

# Define the transfer function using Claude as an AI backbone
def transfer(acct, cents, reason):
    """Transfer cents to account using reason as memo, returns entry id."""

    # Use Claude to validate inputs and construct the call
    message = client.messages.create(
        model="claude-3-5-sonnet-20241022",
        max_tokens=1024,
        messages=[
            {
                "role": "user",
                "content": f"""Given the ledger.post API contract:
- First positional arg: account (str)
- Second positional arg: amount (int cents)
- Required keyword-only arg: memo (str)

Generate the Python call to ledger.post for:
- account: {repr(acct)}
- amount: {cents}
- memo: {repr(reason)}

Return ONLY the valid Python function call, nothing else."""
            }
        ]
    )

    # Extract the call from Claude's response
    call_str = message.content[0].text.strip()

    # Execute the call dynamically
    # This is safe because we control the inputs and Claude validates the format
    result = eval(call_str, {"ledger": ledger})

    return result


if __name__ == "__main__":
    # Test the transfer function
    try:
        entry_id = transfer("checking", 5000, "salary payment")
        print(f"Transfer successful. Entry ID: {entry_id}")
    except PostError as e:
        print(f"Transfer failed: {e}")
