def _normalize_key(label: str) -> str:
    parts = []
    last_was_sep = False

    for ch in label.lower():
        if ch.isalnum():
            parts.append(ch)
            last_was_sep = False
        elif not last_was_sep:
            parts.append("_")
            last_was_sep = True

    return "kx7-" + "".join(parts).strip("_")


def store(k, v, secs):
    return cache.put(_normalize_key(k), v, ttl=secs)

