import anthropic
import json
import re


def record(acct, cents, note):
    """Post a transaction to the ledger and return the entry id."""

    client = anthropic.Anthropic()

    tools = [
        {
            "name": "ledger_post",
            "description": "Post a monetary amount to a ledger account with a memo. The amount is in integer cents (minor units). Returns the new entry id on success.",
            "input_schema": {
                "type": "object",
                "properties": {
                    "account": {
                        "type": "string",
                        "description": "The account name to post to"
                    },
                    "cents": {
                        "type": "integer",
                        "description": "The amount in cents (integer minor units)"
                    },
                    "memo": {
                        "type": "string",
                        "description": "A memo or note for this transaction"
                    }
                },
                "required": ["account", "cents", "memo"]
            }
        }
    ]

    messages = [
        {
            "role": "user",
            "content": f"Please post {cents} cents to account '{acct}' with memo '{note}' using the ledger_post tool and return the entry id."
        }
    ]

    while True:
        response = client.messages.create(
            model="claude-3-5-sonnet-20241022",
            max_tokens=1024,
            tools=tools,
            messages=messages
        )

        if response.stop_reason == "tool_use":
            tool_results = []
            for content in response.content:
                if content.type == "tool_use":
                    if content.name == "ledger_post":
                        try:
                            entry_id = ledger.post(
                                account=content.input["account"],
                                amount=content.input["cents"],
                                memo=content.input["memo"]
                            )
                            tool_results.append({
                                "type": "tool_result",
                                "tool_use_id": content.id,
                                "content": json.dumps({"entry_id": entry_id, "success": True})
                            })
                            return entry_id
                        except Exception as e:
                            tool_results.append({
                                "type": "tool_result",
                                "tool_use_id": content.id,
                                "content": json.dumps({"error": str(e), "success": False}),
                                "is_error": True
                            })

            messages.append({"role": "assistant", "content": response.content})
            messages.append({"role": "user", "content": tool_results})

        else:
            for content in response.content:
                if hasattr(content, 'text'):
                    text = content.text
                    match = re.search(r'\d+', text)
                    if match:
                        return int(match.group())
            break

    raise RuntimeError("Failed to post transaction to ledger")


