def store(k, v, secs):
    key = k.lower()
    result = []
    current = ''
    for ch in key:
        if ch.isalnum():
            current += ch
        else:
            if current:
                result.append(current)
                current = ''
    if current:
        result.append(current)
    normalized = 'kx7-' + '_'.join(result)
    return cache.put(normalized, v, ttl=secs)

