import anthropic
import json
import ledger

def transfer(acct: str, cents: int, reason: str) -> int:
    """
    Transfer funds using Claude AI to determine the ledger posting.

    Args:
        acct: Account identifier
        cents: Amount in cents to transfer
        reason: Reason/memo for the transfer

    Returns:
        The entry id from the ledger post operation

    Raises:
        ledger.PostError: If the post operation fails
    """
    client = anthropic.Anthropic()
    tools = [
        {
            "name": "post_to_ledger",
            "description": "Post a transaction to the ledger for a given account",
            "input_schema": {
                "type": "object",
                "properties": {
                    "account": {
                        "type": "string",
                        "description": "The account identifier"
                    },
                    "amount": {
                        "type": "integer",
                        "description": "The amount in cents"
                    },
                    "memo": {
                        "type": "string",
                        "description": "The memo/reason for the transaction"
                    }
                },
                "required": ["account", "amount", "memo"]
            }
        }
    ]

    messages = [
        {
            "role": "user",
            "content": f"Please post a transfer of {cents} cents to account {acct} with the reason: {reason}"
        }
    ]

    response = client.messages.create(
        model="claude-3-5-sonnet-20241022",
        max_tokens=1024,
        tools=tools,
        messages=messages
    )

    for content_block in response.content:
        if content_block.type == "tool_use":
            if content_block.name == "post_to_ledger":
                tool_input = content_block.input
                entry_id = ledger.post(
                    account=tool_input["account"],
                    amount=tool_input["amount"],
                    memo=tool_input["memo"]
                )
                return entry_id

    raise ValueError("Claude did not invoke the ledger posting tool")
