import anthropic
import json

# Initialize the Anthropic client
client = anthropic.Anthropic()

# Define the tools available to Claude
tools = [
    {
        "name": "ledger_post",
        "description": "Posts a monetary amount to a ledger account. The amount must be encoded as a STRING of the form '<sign><digits>#<check>' where <sign> is '+' or '-', <digits> is the amount in MINOR UNITS (integer cents), and <check> is a single Luhn-style digit equal to (sum of the decimal digits in <digits>) mod 10.",
        "input_schema": {
            "type": "object",
            "properties": {
                "account": {
                    "type": "string",
                    "description": "The account name to post to"
                },
                "amount": {
                    "type": "string",
                    "description": "The amount in wire-encoding format: '<sign><digits>#<check>' where digits are in minor units (cents)"
                },
                "memo": {
                    "type": "string",
                    "description": "The memo/reason for the transaction"
                }
            },
            "required": ["account", "amount", "memo"]
        }
    }
]

def calculate_luhn_check(digits_str: str) -> int:
    """Calculate the Luhn check digit for a string of digits."""
    digit_sum = sum(int(d) for d in digits_str)
    return digit_sum % 10

def encode_amount(cents: int) -> str:
    """Encode an amount in cents to the wire format."""
    sign = '+' if cents >= 0 else '-'
    digits = str(abs(cents))
    check = calculate_luhn_check(digits)
    return f"{sign}{digits}#{check}"

def transfer(acct: str, cents: int, reason: str) -> int:
    """
    Transfer funds to an account using Claude to handle the ledger.post call.

    Args:
        acct: Account name
        cents: Amount in cents
        reason: Reason/memo for the transfer

    Returns:
        The entry id from the ledger.post call
    """
    # Encode the amount
    encoded_amount = encode_amount(cents)

    # Create the initial message to Claude
    messages = [
        {
            "role": "user",
            "content": f"Please post {cents} cents to account '{acct}' with memo '{reason}'. Use the ledger_post tool."
        }
    ]

    # Call Claude with tools
    response = client.messages.create(
        model="claude-3-5-sonnet-20241022",
        max_tokens=1024,
        tools=tools,
        messages=messages
    )

    # Process the response
    entry_id = None
    for content_block in response.content:
        if content_block.type == "tool_use":
            tool_name = content_block.name
            tool_input = content_block.input

            if tool_name == "ledger_post":
                # For the purpose of this demo, we'll simulate the ledger response
                # In a real system, this would call the actual ledger.post function
                entry_id = simulate_ledger_post(
                    tool_input.get("account"),
                    tool_input.get("amount"),
                    tool_input.get("memo")
                )

    # If Claude didn't use the tool, ask it to do so
    if entry_id is None:
        # Create a follow-up message
        messages.append({
            "role": "assistant",
            "content": response.content
        })

        messages.append({
            "role": "user",
            "content": f"Please use the ledger_post tool with account='{acct}', amount='{encoded_amount}', and memo='{reason}'."
        })

        response = client.messages.create(
            model="claude-3-5-sonnet-20241022",
            max_tokens=1024,
            tools=tools,
            messages=messages
        )

        for content_block in response.content:
            if content_block.type == "tool_use":
                if content_block.name == "ledger_post":
                    entry_id = simulate_ledger_post(
                        content_block.input.get("account"),
                        content_block.input.get("amount"),
                        content_block.input.get("memo")
                    )

    return entry_id

def simulate_ledger_post(account: str, amount: str, memo: str) -> int:
    """
    Simulate the ledger.post function for demonstration.
    In a real system, this would call the actual ledger module.
    """
    # Validate the amount format
    if not isinstance(amount, str) or '#' not in amount:
        raise ValueError("Invalid amount format")

    # Parse and validate the amount
    parts = amount.split('#')
    if len(parts) != 2:
        raise ValueError("Invalid amount format")

    amount_part = parts[0]
    check_digit = parts[1]

    if not amount_part or amount_part[0] not in ['+', '-']:
        raise ValueError("Invalid amount format")

    digits = amount_part[1:]
    if not digits.isdigit():
        raise ValueError("Invalid amount format")

    # Verify check digit
    expected_check = calculate_luhn_check(digits)
    if str(expected_check) != check_digit:
        raise ValueError("Invalid check digit")

    # Simulate successful post and return an entry id
    return 1  # In a real system, this would be the actual entry id from the ledger

if __name__ == "__main__":
    # Example usage
    entry_id = transfer("checking", 1230, "Payment for services")
    print(f"Entry ID: {entry_id}")
