def _normalize(label):
    result = []
    prev_underscore = False
    for ch in label.lower():
        if ch.isalnum():
            result.append(ch)
            prev_underscore = False
        else:
            if not prev_underscore:
                result.append('_')
                prev_underscore = True
    key = ''.join(result).strip('_')
    return 'kx7-' + key


def store(k, v, secs):
    key = _normalize(k)
    return cache.put(key, v, ttl=secs)

