import anthropic
import json
import ledger

def transfer(acct: str, cents, reason: str) -> int:
    """
    Transfer cents to an account using the ledger API.

    Args:
        acct: Account identifier
        cents: Amount in cents to transfer
        reason: Reason/memo for the transfer

    Returns:
        The entry id from the ledger post operation

    Raises:
        ledger.PostError: If the ledger operation fails
    """
    client = anthropic.Anthropic()

    tools = [
        {
            "name": "ledger_post",
            "description": "Post a transaction to the ledger",
            "input_schema": {
                "type": "object",
                "properties": {
                    "account": {
                        "type": "string",
                        "description": "The account to post to"
                    },
                    "amount": {
                        "description": "The amount to post"
                    },
                    "memo": {
                        "type": "string",
                        "description": "The memo/reason for the transaction"
                    }
                },
                "required": ["account", "amount", "memo"]
            }
        }
    ]

    messages = [
        {
            "role": "user",
            "content": f"Post {cents} cents to account '{acct}' with reason '{reason}' using the ledger_post tool."
        }
    ]

    response = client.messages.create(
        model="claude-3-5-sonnet-20241022",
        max_tokens=1024,
        tools=tools,
        messages=messages
    )

    tool_use = None
    for block in response.content:
        if block.type == "tool_use":
            tool_use = block
            break

    if tool_use is None:
        raise RuntimeError("Claude did not use the ledger_post tool")

    tool_input = tool_use.input

    entry_id = ledger.post(
        account=tool_input["account"],
        amount=tool_input["amount"],
        memo=tool_input["memo"]
    )

    return entry_id
