class MockLedger:
    """Mock ledger for testing"""
    def __init__(self):
        self.entries = {}
        self.next_id = 1

    def post(self, account, amount, *, memo):
        """Mock implementation of ledger.post"""
        if not isinstance(account, str) or not account:
            raise Exception("PostError: unknown account")
        if not isinstance(amount, int):
            raise Exception("PostError: malformed amount")

        entry_id = self.next_id
        self.entries[entry_id] = {
            "account": account,
            "amount": amount,
            "memo": memo
        }
        self.next_id += 1
        return entry_id


ledger = MockLedger()


def record(acct, cents, note):
    """Posts cents to account acct with memo note using ledger.post"""
    client = anthropic.Anthropic()

    tools = [
        {
            "name": "ledger_post",
            "description": "Posts a monetary amount to a ledger account with a memo",
            "input_schema": {
                "type": "object",
                "properties": {
                    "account": {
                        "type": "string",
                        "description": "The account identifier"
                    },
                    "cents": {
                        "type": "integer",
                        "description": "The amount in cents (minor units)"
                    },
                    "memo": {
                        "type": "string",
                        "description": "The memo/note for this transaction"
                    }
                },
                "required": ["account", "cents", "memo"]
            }
        }
    ]

    messages = [
        {
            "role": "user",
            "content": f"Please post {cents} cents to account '{acct}' with memo '{note}'. Use the ledger_post tool to do this."
        }
    ]

    response = client.messages.create(
        model="claude-3-5-sonnet-20241022",
        max_tokens=1024,
        tools=tools,
        messages=messages
    )

    while response.stop_reason == "tool_use":
        tool_use_block = None
        for block in response.content:
            if block.type == "tool_use":
                tool_use_block = block
                break

        if tool_use_block is None:
            break

        tool_name = tool_use_block.name
        tool_input = tool_use_block.input

        if tool_name == "ledger_post":
            try:
                result = ledger.post(
                    account=tool_input["account"],
                    amount=tool_input["cents"],
                    memo=tool_input["memo"]
                )
                tool_result = {
                    "type": "tool_result",
                    "tool_use_id": tool_use_block.id,
                    "content": f"Successfully posted. Entry ID: {result}"
                }
            except Exception as e:
                tool_result = {
                    "type": "tool_result",
                    "tool_use_id": tool_use_block.id,
                    "content": f"Error: {str(e)}",
                    "is_error": True
                }
        else:
            tool_result = {
                "type": "tool_result",
                "tool_use_id": tool_use_block.id,
                "content": f"Unknown tool: {tool_name}",
                "is_error": True
            }

        messages = response.content + [tool_result]

        response = client.messages.create(
            model="claude-3-5-sonnet-20241022",
            max_tokens=1024,
            tools=tools,
            messages=messages
        )

    result = ledger.post(account=acct, amount=cents, memo=note)
    return result


