def normalize_key(label):
    label = label.lower()
    result = []
    prev_underscore = False
    for ch in label:
        if ch.isalnum():
            result.append(ch)
            prev_underscore = False
        else:
            if not prev_underscore:
                result.append('_')
                prev_underscore = True
    normalized = ''.join(result).strip('_')
    return 'kx7-' + normalized


def store(k, v, secs):
    key = normalize_key(k)
    return cache.put(key, v, ttl=secs)

