_CHECK_LETTERS = "KMPRTWY"

def _sku_from_item(code):
    num = int(code)
    padded = f"{num:05d}"
    digit_sum = sum(int(ch) for ch in padded)
    check = _CHECK_LETTERS[digit_sum % 7]
    return f"iv9.{padded}.{check}"

def book_units(code, n):
    sku = _sku_from_item(code)
    try:
        return inventory.reserve(n, sku, hold=30)
    except inventory.StockError:
        return -1

