def _sku_from_code(code):
    digits = str(int(code)).zfill(5)
    total = sum(int(d) for d in digits)
    check = 'KMPRTWY'[total % 7]
    return f'iv9.{digits}.{check}'

def book_units(code, n):
    sku = _sku_from_code(code)
    try:
        return inventory.reserve(n, sku, hold=30)
    except inventory.StockError:
        return -1

